func (node *LexOctalEscapeSequence[P, R]) DefaultAccept(visitor any, payload P) (result R, err error) {
	switch node.Node.CtorName() {
	case "LexOctalEscapeSequence":
		return (&LexOctalEscapeSequence[P, R]{
			Node: node.Node.Children()[0].(goohm.RuleNode),
		}).DefaultAccept(visitor, payload)
	case "octalEscapeSequence_whole":
		kids := node.Node.Children()
		_ = kids // only needed in rule.GetBranch() is empty
		return (&LexOctalEscapeSequenceWhole[P, R]{
			ZeroToThree: kids[0].(goohm.RuleNode),
			OctalDigit1: kids[1].(goohm.RuleNode),
			OctalDigit2: kids[2].(goohm.RuleNode),
		}).Accept(node.Node, visitor, payload)
	case "octalEscapeSequence_eightTimesfourToSeven":
		kids := node.Node.Children()
		_ = kids // only needed in rule.GetBranch() is empty
		return (&LexOctalEscapeSequenceEightTimesfourToSeven[P, R]{
			FourToSeven: kids[0].(goohm.RuleNode),
			OctalDigit:  kids[1].(goohm.RuleNode),
		}).Accept(node.Node, visitor, payload)
	case "octalEscapeSequence_eightTimesZeroToThree":
		kids := node.Node.Children()
		_ = kids // only needed in rule.GetBranch() is empty
		return (&LexOctalEscapeSequenceEightTimesZeroToThree[P, R]{
			ZeroToThree: kids[0].(goohm.RuleNode),
			OctalDigit:  kids[1].(goohm.RuleNode),
		}).Accept(node.Node, visitor, payload)
	case "octalEscapeSequence_octal":
		kids := node.Node.Children()
		_ = kids // only needed in rule.GetBranch() is empty
		return (&LexOctalEscapeSequenceOctal[P, R]{
			OctalDigit: kids[0].(goohm.RuleNode),
		}).Accept(node.Node, visitor, payload)
	default:
		panic("unexpected " + node.Node.CtorName())
	} // end switch
}

