func (node *IterationStatement[P, R]) DefaultAccept(visitor any, payload P) (result R, err error) {
	switch node.Node.CtorName() {
	case "IterationStatement":
		return (&IterationStatement[P, R]{
			Node: node.Node.Children()[0].(goohm.RuleNode),
		}).DefaultAccept(visitor, payload)
	case "IterationStatement_doWhile":
		kids := node.Node.Children()
		_ = kids // only needed in rule.GetBranch() is empty
		return (&IterationStatementDoWhile[P, R]{
			Do:         kids[0].(goohm.RuleNode),
			Statement:  kids[1].(goohm.RuleNode),
			While:      kids[2].(goohm.RuleNode),
			Term1:      kids[3].(goohm.TerminalNode),
			Expression: kids[4],
			Term2:      kids[5].(goohm.TerminalNode),
			Sc:         kids[6].(goohm.RuleNode),
		}).Accept(node.Node, visitor, payload)
	case "IterationStatement_whileDo":
		kids := node.Node.Children()
		_ = kids // only needed in rule.GetBranch() is empty
		return (&IterationStatementWhileDo[P, R]{
			While:      kids[0].(goohm.RuleNode),
			Term1:      kids[1].(goohm.TerminalNode),
			Expression: kids[2],
			Term2:      kids[3].(goohm.TerminalNode),
			Statement:  kids[4].(goohm.RuleNode),
		}).Accept(node.Node, visitor, payload)
	case "IterationStatement_for3":
		kids := node.Node.Children()
		_ = kids // only needed in rule.GetBranch() is empty
		return (&IterationStatementFor3[P, R]{
			For:         kids[0].(goohm.RuleNode),
			Term1:       kids[1].(goohm.TerminalNode),
			Expression1: kids[2].(goohm.OptNode),
			Term2:       kids[3].(goohm.TerminalNode),
			Expression2: kids[4].(goohm.OptNode),
			Term3:       kids[5].(goohm.TerminalNode),
			Expression3: kids[6].(goohm.OptNode),
			Term4:       kids[7].(goohm.TerminalNode),
			Statement:   kids[8].(goohm.RuleNode),
		}).Accept(node.Node, visitor, payload)
	case "IterationStatement_for3var":
		kids := node.Node.Children()
		_ = kids // only needed in rule.GetBranch() is empty
		return (&IterationStatementFor3var[P, R]{
			For:                     kids[0].(goohm.RuleNode),
			Term1:                   kids[1].(goohm.TerminalNode),
			Var:                     kids[2].(goohm.RuleNode),
			VariableDeclarationList: kids[3],
			Term2:                   kids[4].(goohm.TerminalNode),
			Expression1:             kids[5].(goohm.OptNode),
			Term3:                   kids[6].(goohm.TerminalNode),
			Expression2:             kids[7].(goohm.OptNode),
			Term4:                   kids[8].(goohm.TerminalNode),
			Statement:               kids[9].(goohm.RuleNode),
		}).Accept(node.Node, visitor, payload)
	case "IterationStatement_forIn":
		kids := node.Node.Children()
		_ = kids // only needed in rule.GetBranch() is empty
		return (&IterationStatementForIn[P, R]{
			For:                    kids[0].(goohm.RuleNode),
			Term1:                  kids[1].(goohm.TerminalNode),
			LeftHandSideExpression: kids[2].(goohm.RuleNode),
			In:                     kids[3].(goohm.RuleNode),
			Expression:             kids[4],
			Term2:                  kids[5].(goohm.TerminalNode),
			Statement:              kids[6].(goohm.RuleNode),
		}).Accept(node.Node, visitor, payload)
	case "IterationStatement_forInVar":
		kids := node.Node.Children()
		_ = kids // only needed in rule.GetBranch() is empty
		return (&IterationStatementForInVar[P, R]{
			For:                 kids[0].(goohm.RuleNode),
			Term1:               kids[1].(goohm.TerminalNode),
			Var:                 kids[2].(goohm.RuleNode),
			VariableDeclaration: kids[3],
			In:                  kids[4].(goohm.RuleNode),
			Expression:          kids[5],
			Term2:               kids[6].(goohm.TerminalNode),
			Statement:           kids[7].(goohm.RuleNode),
		}).Accept(node.Node, visitor, payload)
	default:
		panic("unexpected " + node.Node.CtorName())
	} // end switch
}

