// Accept implementation for FunctionExpression
//
// FunctionExpression
// = function identifier "(" FormalParameterList ")" "{" FunctionBody "}"  -- named
// | function "(" FormalParameterList ")" "{" FunctionBody "}"             -- anonymous
func (node *FunctionExpression[P, R]) Accept(this goohm.Node, visitor any, payload P) (result R, err error) {
	goohm.AssertName(this, "FunctionExpression")
	if v, ok := visitor.(Switcher_FunctionExpression[P, R]); ok {
		v.SwitchFunctionExpression(node)
		return
	}
	if v, ok := visitor.(SwitcherE_FunctionExpression[P, R]); ok {
		err = v.SwitchFunctionExpression(node)
		return
	}
	if v, ok := visitor.(SwitcherP_FunctionExpression[P, R]); ok {
		v.SwitchFunctionExpression(node, payload)
		return
	}
	if v, ok := visitor.(SwitcherPE_FunctionExpression[P, R]); ok {
		err = v.SwitchFunctionExpression(node, payload)
		return
	}
	if v, ok := visitor.(SwitcherR_FunctionExpression[P, R]); ok {
		result = v.SwitchFunctionExpression(node)
		return
	}
	if v, ok := visitor.(SwitcherRE_FunctionExpression[P, R]); ok {
		result, err = v.SwitchFunctionExpression(node)
		return
	}
	if v, ok := visitor.(SwitcherPR_FunctionExpression[P, R]); ok {
		result = v.SwitchFunctionExpression(node, payload)
		return
	}
	if v, ok := visitor.(SwitcherPRE_FunctionExpression[P, R]); ok {
		result, err = v.SwitchFunctionExpression(node, payload)
		return
	}
	goohm.TypeCheckMethod[P, R](visitor, "FunctionExpression")
	return node.DefaultAccept(visitor, payload)
}

func (node *FunctionExpression[P, R]) DefaultAccept(visitor any, payload P) (result R, err error) {
	switch node.Node.CtorName() {
	case "FunctionExpression":
		return (&FunctionExpression[P, R]{
			Node: node.Node.Children()[0].(goohm.RuleNode),
		}).DefaultAccept(visitor, payload)
	case "FunctionExpression_named":
		kids := node.Node.Children()
		_ = kids // only needed in rule.GetBranch() is empty
		return (&FunctionExpressionNamed[P, R]{
			Function:            kids[0].(goohm.RuleNode),
			Identifier:          kids[1].(goohm.RuleNode),
			Term1:               kids[2].(goohm.TerminalNode),
			FormalParameterList: kids[3].(goohm.RuleNode),
			Term2:               kids[4].(goohm.TerminalNode),
			Term3:               kids[5].(goohm.TerminalNode),
			FunctionBody:        kids[6].(goohm.RuleNode),
			Term4:               kids[7].(goohm.TerminalNode),
		}).Accept(node.Node, visitor, payload)
	case "FunctionExpression_anonymous":
		kids := node.Node.Children()
		_ = kids // only needed in rule.GetBranch() is empty
		return (&FunctionExpressionAnonymous[P, R]{
			Function:            kids[0].(goohm.RuleNode),
			Term1:               kids[1].(goohm.TerminalNode),
			FormalParameterList: kids[2].(goohm.RuleNode),
			Term2:               kids[3].(goohm.TerminalNode),
			Term3:               kids[4].(goohm.TerminalNode),
			FunctionBody:        kids[5].(goohm.RuleNode),
			Term4:               kids[6].(goohm.TerminalNode),
		}).Accept(node.Node, visitor, payload)
	default:
		panic("unexpected " + node.Node.CtorName())
	} // end switch
}

