func (node *FormalParameterList[P, R]) DefaultAccept(visitor any, payload P) (result R, err error) {
	result, err = node.AcceptListOf(visitor, payload)
	return
}

func (node *FormalParameterList[P, R]) AcceptListOf(visitor any, payload P) (result R, err error) {
	// BuiltinHOR
	// FormalParameter
	fn_elem := func(n goohm.Node) (result R) {
		kids := n.Children()
		result, err = (&FormalParameter[P, R]{
			Identifier: kids[0].(goohm.RuleNode),
		}).Accept(n, visitor, payload)
		return
	}
	fn_sep := func(n goohm.Node) (result R) {
		if v, ok := visitor.(goohm.TerminalVisitor); ok {
			v.Terminal(n.(goohm.TerminalNode))
		}
		return
	}
	goohm.AcceptBuiltinHOR(node.ListOf, fn_elem, fn_sep)
	return
}

